// MsgServer is the server API for Msg service.
// All implementations must embed UnimplementedMsgServer
// for forward compatibility.
//
// Msg defines the security module's message service
type MsgServer interface {
	// AddTrustedPeer adds a trusted peer
	AddTrustedPeer(context.Context, *MsgAddTrustedPeer) (*MsgAddTrustedPeerResponse, error)
	// RemoveTrustedPeer removes a trusted peer
	RemoveTrustedPeer(context.Context, *MsgRemoveTrustedPeer) (*MsgRemoveTrustedPeerResponse, error)
	// BanPeer bans a peer
	BanPeer(context.Context, *MsgBanPeer) (*MsgBanPeerResponse, error)
	// UnbanPeer unbans a peer
	UnbanPeer(context.Context, *MsgUnbanPeer) (*MsgUnbanPeerResponse, error)
	// UpdatePeerReputation manually updates peer reputation
	UpdatePeerReputation(context.Context, *MsgUpdatePeerReputation) (*MsgUpdatePeerReputationResponse, error)
	// ResolveForkAlert resolves a fork alert
	ResolveForkAlert(context.Context, *MsgResolveForkAlert) (*MsgResolveForkAlertResponse, error)
	// ResolvePartitionAlert resolves a partition alert
	ResolvePartitionAlert(context.Context, *MsgResolvePartitionAlert) (*MsgResolvePartitionAlertResponse, error)
	// RegisterValidatorSecurity registers security info for a validator
	RegisterValidatorSecurity(context.Context, *MsgRegisterValidatorSecurity) (*MsgRegisterValidatorSecurityResponse, error)
	// UpdateValidatorSecurity updates validator security information
	UpdateValidatorSecurity(context.Context, *MsgUpdateValidatorSecurity) (*MsgUpdateValidatorSecurityResponse, error)
	// RegisterSentryNode registers a sentry node
	RegisterSentryNode(context.Context, *MsgRegisterSentryNode) (*MsgRegisterSentryNodeResponse, error)
	// RemoveSentryNode removes a sentry node
	RemoveSentryNode(context.Context, *MsgRemoveSentryNode) (*MsgRemoveSentryNodeResponse, error)
	// ReportDoubleSign reports double signing evidence
	ReportDoubleSign(context.Context, *MsgReportDoubleSign) (*MsgReportDoubleSignResponse, error)
	// AcknowledgeValidatorAlert acknowledges a validator alert
	AcknowledgeValidatorAlert(context.Context, *MsgAcknowledgeValidatorAlert) (*MsgAcknowledgeValidatorAlertResponse, error)
	// TriggerFailover triggers validator failover
	TriggerFailover(context.Context, *MsgTriggerFailover) (*MsgTriggerFailoverResponse, error)
	// RegisterHardwareWallet registers a hardware wallet
	RegisterHardwareWallet(context.Context, *MsgRegisterHardwareWallet) (*MsgRegisterHardwareWalletResponse, error)
	// CreateMultiSigWallet creates a multi-signature wallet
	CreateMultiSigWallet(context.Context, *MsgCreateMultiSigWallet) (*MsgCreateMultiSigWalletResponse, error)
	// ProposeMultiSigTransaction proposes a multi-sig transaction
	ProposeMultiSigTransaction(context.Context, *MsgProposeMultiSigTransaction) (*MsgProposeMultiSigTransactionResponse, error)
	// SignMultiSigTransaction signs a pending multi-sig transaction
	SignMultiSigTransaction(context.Context, *MsgSignMultiSigTransaction) (*MsgSignMultiSigTransactionResponse, error)
	// ExecuteMultiSigTransaction executes a fully signed multi-sig transaction
	ExecuteMultiSigTransaction(context.Context, *MsgExecuteMultiSigTransaction) (*MsgExecuteMultiSigTransactionResponse, error)
	// ConfigureSocialRecovery configures social recovery
	ConfigureSocialRecovery(context.Context, *MsgConfigureSocialRecovery) (*MsgConfigureSocialRecoveryResponse, error)
	// InitiateRecovery initiates wallet recovery
	InitiateRecovery(context.Context, *MsgInitiateRecovery) (*MsgInitiateRecoveryResponse, error)
	// ApproveRecovery approves a recovery request
	ApproveRecovery(context.Context, *MsgApproveRecovery) (*MsgApproveRecoveryResponse, error)
	// ExecuteRecovery executes a recovery request
	ExecuteRecovery(context.Context, *MsgExecuteRecovery) (*MsgExecuteRecoveryResponse, error)
	// SetSpendingLimits sets spending limits for a wallet
	SetSpendingLimits(context.Context, *MsgSetSpendingLimits) (*MsgSetSpendingLimitsResponse, error)
	// RegisterBiometric registers biometric authentication
	RegisterBiometric(context.Context, *MsgRegisterBiometric) (*MsgRegisterBiometricResponse, error)
	// CreateIncident creates a new incident
	CreateIncident(context.Context, *MsgCreateIncident) (*MsgCreateIncidentResponse, error)
	// UpdateIncident updates an incident
	UpdateIncident(context.Context, *MsgUpdateIncident) (*MsgUpdateIncidentResponse, error)
	// ResolveIncident resolves an incident
	ResolveIncident(context.Context, *MsgResolveIncident) (*MsgResolveIncidentResponse, error)
	// ExecuteResponseAction executes a response action
	ExecuteResponseAction(context.Context, *MsgExecuteResponseAction) (*MsgExecuteResponseActionResponse, error)
	// AddAuditLogEntry adds an audit log entry
	AddAuditLogEntry(context.Context, *MsgAddAuditLogEntry) (*MsgAddAuditLogEntryResponse, error)
	// CreateKeyRotationSchedule creates a key rotation schedule
	CreateKeyRotationSchedule(context.Context, *MsgCreateKeyRotationSchedule) (*MsgCreateKeyRotationScheduleResponse, error)
	// RotateKey manually rotates a key
	RotateKey(context.Context, *MsgRotateKey) (*MsgRotateKeyResponse, error)
	// CreateThresholdScheme creates a threshold signature scheme
	CreateThresholdScheme(context.Context, *MsgCreateThresholdScheme) (*MsgCreateThresholdSchemeResponse, error)
	// SubmitThresholdSignatureShare submits a threshold signature share
	SubmitThresholdSignatureShare(context.Context, *MsgSubmitThresholdSignatureShare) (*MsgSubmitThresholdSignatureShareResponse, error)
	// RegisterZKProofCircuit registers a ZK proof circuit
	RegisterZKProofCircuit(context.Context, *MsgRegisterZKProofCircuit) (*MsgRegisterZKProofCircuitResponse, error)
	// SubmitZKProof submits a zero-knowledge proof
	SubmitZKProof(context.Context, *MsgSubmitZKProof) (*MsgSubmitZKProofResponse, error)
	// GenerateQuantumResistantKey generates a quantum-resistant key
	GenerateQuantumResistantKey(context.Context, *MsgGenerateQuantumResistantKey) (*MsgGenerateQuantumResistantKeyResponse, error)
	// CreateMixingPool creates a mixing pool
	CreateMixingPool(context.Context, *MsgCreateMixingPool) (*MsgCreateMixingPoolResponse, error)
	// JoinMixingPool joins a mixing pool
	JoinMixingPool(context.Context, *MsgJoinMixingPool) (*MsgJoinMixingPoolResponse, error)
	// ExecuteMixing executes mixing in a pool
	ExecuteMixing(context.Context, *MsgExecuteMixing) (*MsgExecuteMixingResponse, error)
	// GenerateStealthAddress generates a stealth address
	GenerateStealthAddress(context.Context, *MsgGenerateStealthAddress) (*MsgGenerateStealthAddressResponse, error)
	// CreateRingSignature creates a ring signature
	CreateRingSignature(context.Context, *MsgCreateRingSignature) (*MsgCreateRingSignatureResponse, error)
	// CreateConfidentialTransaction creates a confidential transaction
	CreateConfidentialTransaction(context.Context, *MsgCreateConfidentialTransaction) (*MsgCreateConfidentialTransactionResponse, error)
	// UpdateParams updates the module parameters
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	mustEmbedUnimplementedMsgServer()
}

